mapper.select:
SELECT 
FROM sys_user_role

    AND tenant_id = #{tenantId}
    AND user_id = #{userId}
    AND role_id = #{roleId}

ORDER BY 1

mapper.delete:
DELETE FROM sys_user_role

    AND tenant_id = #{tenantId}
    AND user_id = #{userId}
    AND role_id = #{roleId}

mapper.select:
SELECT DISTINCT ur.role_id
FROM sys_user_role ur
INNER JOIN sys_role r ON r.id = ur.role_id AND r.tenant_id = ur.tenant_id AND r.deleted = 0
WHERE ur.tenant_id = #{tenantId}
  AND ur.user_id = #{userId}
  AND r.status = '0'

SELECT DISTINCT r.role_code
FROM sys_user_role ur
INNER JOIN sys_role r ON r.id = ur.role_id AND r.tenant_id = ur.tenant_id AND r.deleted = 0
WHERE ur.tenant_id = #{tenantId}
  AND ur.user_id = #{userId}
  AND r.status = '0'
